function validate([n]) {
  if (typeof n !== 'string' || !/^[1-9][0-9]*$/.test(n)) return 'n must be a decimal string without leading zeros.';
  if (n.length > 19) return 'n must be between 3 and 10^18.';
  const value = BigInt(n);
  if (value < 3n || value > 10n ** 18n) return 'n must be between 3 and 10^18.';
  return null;
}

