function smallestGoodBase(n) {
  const target = BigInt(n);
  const maxDigits = target.toString(2).length;

  for (let digits = maxDigits; digits >= 3; digits--) {
    const power = BigInt(digits - 1);
    let base = BigInt(Math.floor(Number(target) ** (1 / (digits - 1))));
    while (base ** power > target) base--;
    while ((base + 1n) ** power <= target) base++;

    let sum = 0n;
    let term = 1n;
    for (let i = 0; i < digits; i++) {
      sum += term;
      term *= base;
    }
    if (sum === target) {
      return base.toString();
    }
  }
  return (target - 1n).toString();
}

