function smallestGoodBase(n) {
  // For every digit count, most digits first, binary search a base whose all-ones number equals n.
  const value = BigInt(n);
  const repunit = (base, count) => {
    let total = 0n;
    for (let i = 0; i < count; i++) {
      total = total * base + 1n;
      if (total > value) return total;
    }
    return total;
  };
  for (let count = 64; count >= 2; count--) {
    let lo = 2n, hi = value - 1n;
    while (lo <= hi) {
      const mid = (lo + hi) / 2n;
      const total = repunit(mid, count);
      if (total === value) return mid.toString();
      if (total < value) lo = mid + 1n; else hi = mid - 1n;
    }
  }
  return 'none';
}

