function generate(rand, size) {
  const LIMIT = 10n ** 18n;
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const bigBelow = (limit) => {
    // A random BigInt in [0, limit) built from random decimal digits.
    let digits = '';
    for (let i = 0; i < 19; i++) digits += String(int(0, 9));
    return BigInt(digits) % limit;
  };
  const repunit = (base, count) => {
    let total = 0n;
    for (let i = 0; i < count; i++) total = total * base + 1n;
    return total;
  };
  if (size === 'small') {
    const r = rand();
    if (r < 0.5) return [String(int(3, 400))];
    for (;;) {
      const base = BigInt(int(2, 12));
      const count = int(2, 6);
      const value = repunit(base, count);
      if (value >= 3n && value <= 100000n) return [String(value)];
    }
  }
  const r = rand();
  if (r < 0.4) {
    const value = 3n + bigBelow(LIMIT - 2n);
    return [String(value)];
  }
  for (;;) {
    const count = int(3, 60);
    const top = Math.floor(1e18 ** (1 / (count - 1)));
    const base = BigInt(int(2, Math.max(2, top)));
    const value = repunit(base, count);
    if (value >= 3n && value <= LIMIT) return [String(value)];
  }
}
